const items = $input.all();
const seen = new Map();

const clean = (value) =>
  String(value || '').toLowerCase().trim().replace(/\s+/g, ' ');

for (const item of items) {
  const lead = item.json;
  const name = clean(lead.business_name);
  const address = clean(lead.address);
  const phone = String(lead.phone || '').replace(/\D/g, '');
  const city = clean(lead.city);

  const key = address
    ? `${name}||${address}`
    : phone
      ? `${name}||${phone}`
      : `${name}||${city}`;

  if (!seen.has(key)) {
    seen.set(key, item);
  } else {
    const existing = seen.get(key);

    if (lead.source === 'gmb' && existing.json.source !== 'gmb') {
      seen.set(key, item);
    }
  }
}

return Array.from(seen.values());

const c = $input.first().json;
const errors = [];

const business_type = String(c.business_type || '').trim();
const city = String(c.city || '').trim();
const country = String(c.country || '').trim().toUpperCase();
const source = String(c.source || 'gmb').trim().toLowerCase();

if (!business_type) errors.push('business_type missing');
if (!city) errors.push('city missing');
if (!/^[A-Z]{2}$/.test(country)) errors.push('country must be 2 letters, e.g. AU');
if (!['gmb', 'yelp'].includes(source)) errors.push('source must be "gmb" or "yelp" (run twice for both)');

if (source === 'gmb' && !$env.GOOGLE_API_KEY) errors.push('GOOGLE_API_KEY not set');
if (source === 'yelp' && !$env.YELP_API_KEY) errors.push('YELP_API_KEY not set');


const MAX = { gmb: 60, yelp: 150 };
let limit = Math.floor(Number(c.limit));
if (!Number.isFinite(limit) || limit < 1) limit = 10;
limit = Math.min(limit, MAX[source] || 60);

const search_query =
  String(c.search_query || '').trim() || `${business_type} in ${city}, ${country}`;

if (errors.length) {
  throw new Error('Invalid input: ' + errors.join(', '));
}

return [{
  json: {
    ...c,
    business_type,
    city,
    country,
    source,
    limit,
    search_query,
    location: String(c.location || '').trim() || `${city}, ${country}`,
    started_at: c.started_at || new Date().toISOString(),
  },
}];

const cfg = $('Code — Validate Input').first().json;
const campaignId = $('Postgres — Create Campaign').first().json.id;
const sources = cfg.source === 'both' ? ['yelp', 'gmb'] : [cfg.source];

return sources.map((active_source) => ({
  json: {
    ...cfg,
    campaign_id: campaignId,
    active_source,
  },
}));

const cfg = $('Code — Expand Sources').first().json;
const limit = Number(cfg.limit) || 10;

const pages = $('Google Places — Text Search').all();

const existing = new Set(
  $input.all().map((i) => i.json.external_id).filter(Boolean)
);

const seenIds = new Set();
const fresh = [];

for (const page of pages) {
  for (const p of page.json.places || []) {
    const id = String(p.id || '').replace('places/', '');
    if (!id || seenIds.has(id)) continue;
    seenIds.add(id);
    if (existing.has(`gmb_${id}`)) continue;
    if (p.businessStatus === 'CLOSED_PERMANENTLY') continue;
    fresh.push(p);
  }
}

fresh.sort((a, b) => (b.websiteUri ? 1 : 0) - (a.websiteUri ? 1 : 0));

return fresh.slice(0, limit).map((p) => {
  const rawId = String(p.id || '').replace('places/', '');
  const website = String(p.websiteUri || '').trim();
  const hasWebsite = website.length > 0;

  return {
    json: {
      external_id: `gmb_${rawId}`,
      source: 'gmb',
      business_name: p.displayName?.text || '',
      category: p.primaryType || '',
      phone: p.nationalPhoneNumber || '',
      address: p.formattedAddress || '',
      city: cfg.city || '',
      state: '',
      country: cfg.country || 'AU',
      website_url: website,
      google_url: `https://www.google.com/maps/place/?q=place_id:${rawId}`,
      rating: p.rating ?? null,
      review_count: p.userRatingCount ?? null,
      search_query: cfg.search_query || '',
      campaign_id: cfg.campaign_id,
      status: hasWebsite ? 'new' : 'no_website',
      failure_reason: hasWebsite ? null : 'No website URL in Google Maps listing',
    },
  };
});

const ids = new Set();
for (const page of $input.all()) {
  for (const p of page.json.places || []) {
    const id = String(p.id || '').replace('places/', '').replace(/[^A-Za-z0-9_-]/g, '');
    if (id) ids.add('gmb_' + id);
  }
}
return [{ json: { ids: [...ids].join('|') || 'none' } }];

