const cfg = $('Code — Validate Input').first().json;
const campaignId = $('Postgres — Create Campaign1').first().json.id;

const safeAll = (name) => { try { return $(name).all(); } catch (e) { return []; } };
const countOf = (name, key) =>
  safeAll(name).reduce((s, p) => s + ((p.json[key] || []).length), 0);

const found =
  countOf('Google Places — Text Search1', 'places') +
  countOf('Yelp API — Search', 'businesses');
const newCandidates = safeAll('Code — Deduplicate').length;
const insertErrors = safeAll('Postgres — Log Insert Error').length;

const startedAt = new Date(cfg.started_at).getTime();

return [{
  json: {
    campaign_id: campaignId,
    leads_found: found,
    leads_processed: newCandidates,
    leads_failed: insertErrors,
    duration_ms: Number.isFinite(startedAt) ? Date.now() - startedAt : 0,
    notes: `WF1 | ${cfg.source} | ${cfg.search_query} | found=${found} new=${newCandidates} insert_errors=${insertErrors}`,
  },
}];

const ids = new Set();
for (const page of $input.all()) {
  for (const b of page.json.businesses || []) {
    const id = String(b.id || '').replace(/[^A-Za-z0-9_-]/g, '');
    if (id) ids.add('yelp_' + id);
  }
}
return [{ json: { ids: [...ids].join('|') || 'none' } }];

