const cfg = $('Code — Expand Sources').first().json;
const limit = Number(cfg.limit) || 10;
const pages = $('Yelp API — Search').all();

const existing = new Set(
  $input.all().map((i) => i.json.external_id).filter(Boolean)
);

const seen = new Set();
const fresh = [];

for (const page of pages) {
  for (const b of page.json.businesses || []) {
    const id = String(b.id || '');
    if (!id || seen.has(id)) continue;
    seen.add(id);
    if (existing.has(`yelp_${id}`)) continue;
    if (b.is_closed) continue;
    fresh.push(b);
  }
}

return fresh.slice(0, limit).map((b) => {
  const yelpPage = String(b.url || '').split('?')[0];
  return {
    json: {
      external_id: `yelp_${b.id}`,
      source: 'yelp',
      business_name: b.name || '',
      category: (b.categories || []).map((c) => c.title).join(', '),
      phone: b.display_phone || b.phone || '',
      address: (b.location?.display_address || []).join(', '),
      city: b.location?.city || cfg.city || '',
      state: b.location?.state || '',
      country: b.location?.country || cfg.country || '',
      website_url: '',
      google_url: null,
      rating: b.rating ?? null,
      review_count: b.review_count ?? null,
      search_query: cfg.search_query || '',
      campaign_id: cfg.campaign_id,
      status: 'no_website',
      failure_reason: `Yelp API does not provide website. Yelp page: ${yelpPage}`,
    },
  };
});
